const scenarios={
  complete:{title:'Complete Portfolio',prompt:'Explain every number and unit, then open each family, holding, Health measure, concentration and trend route.',fixture:'Aarav has all three families and every Health mechanism available.'},
  empty:{title:'Empty Portfolio',prompt:'Enter all three empty families. Try teaching, Arya, capture and manual add without being forced to record anything.',fixture:'Kabir has no holdings or optional context.'},
  mixed:{title:'Mixed partial records',prompt:'Find known, unvalued, invalid, excluded and unclassified records. Explain why there is no net-worth total.',fixture:'Mira has mixed records and partial Health inputs.'},
  manage:{title:'Manage a holding',prompt:'Open a holding. Cancel and fail an edit, save it, review recategorization, simulate conflict and reconcile a lost response.',fixture:'Mira starts with an editable equity mutual-fund record.'},
  delete:{title:'Delete a holding',prompt:'Cancel deletion, simulate a stale impact review, confirm it, then recover a reminder-only failure.',fixture:'Mira has one loan linked to a goal and reminder.'},
  teaching:{title:'Concentration and trend',prompt:'Test zero, one and many supported funds. Confirm the limit never changes and no performance history is invented.',fixture:'Fixture controls switch the contributing fund count.'},
  health:{title:'Portfolio Health',prompt:'Inspect none, partial and full states. Save, fail, retry and clear optional context. Look for any score, band or reward.',fixture:'Start with Mira. Switch accounts for none and full states.'},
  recovery:{title:'Read recovery',prompt:'Test a local failure, stale data, offline with and without cache, reconnection and explicit retry.',fixture:'Each recovery affects only the selected block.'},
  isolation:{title:'Authentication and isolation',prompt:'Lose permission, then switch from Aarav to Meera during a pending read. Verify immediate clearing and late-response discard.',fixture:'Meera has one sparse investment record.'},
  'all-routes':{title:'Every route and control',prompt:'Open every screen, action, disclosure and recovery control with keyboard and pointer.',fixture:'Controlled destinations stand in for production routes.'}
};

const fixtures={
  Aarav:{freshness:'Updated 29 Aug, 10:42 AM',families:{
    Investments:[
      {id:'inv-a1',name:'Long-term equity fund',type:'Equity mutual fund',status:'valued',value:372450,version:4,fields:{'Recorded value':'₹3,72,450','Monthly contribution':'₹12,500','Category':'Equity mutual fund'}},
      {id:'inv-a2',name:'Retirement account',type:'PPF / EPF',status:'valued',value:218730,version:2,fields:{'Recorded value':'₹2,18,730','Contribution cadence':'Monthly','Category':'PPF / EPF'}}],
    Loans:[{id:'loan-a1',name:'Education loan',type:'Personal loan',status:'valued',value:486200,version:3,fields:{'Outstanding balance':'₹4,86,200','Interest rate':'9.4%','Monthly payment':'₹10,850'},links:['Goal: Debt-free buffer','Reminder: Payment on 6th']}],
    Insurance:[{id:'ins-a1',name:'Term cover',type:'Term insurance',status:'excluded',value:null,cover:7200000,version:1,fields:{'Recorded cover':'₹72,00,000','Cash value':'Not applicable','Premium cadence':'Yearly'}}]
  },unclassified:[],income:720000,outflows:96000,emergencyMonths:7.5,healthCover:true,taxUsed:94000},
  Mira:{freshness:'Updated 29 Aug, 10:37 AM',families:{
    Investments:[
      {id:'inv-m1',name:'Growth fund',type:'Equity mutual fund',status:'valued',value:283750,version:5,fields:{'Recorded value':'₹2,83,750','Monthly contribution':'₹8,500','Category':'Equity mutual fund'}},
      {id:'inv-m2',name:'Income fund',type:'Debt mutual fund',status:'valued',value:126430,version:2,fields:{'Recorded value':'₹1,26,430','Monthly contribution':'₹4,000','Category':'Debt mutual fund'}},
      {id:'inv-m3',name:'Workplace grant',type:'ESOP',status:'invalid',value:null,version:1,fields:{'Units granted':'480','Current value':'Invalid recorded value','Grant type':'Options'}}],
    Loans:[{id:'loan-m1',name:'Home loan',type:'Home loan',status:'valued',value:812400,version:6,fields:{'Outstanding balance':'₹8,12,400','Interest rate':'8.65%','Monthly payment':'₹18,900'},links:['Goal: Home loan runway','Reminder: Payment on 4th']}],
    Insurance:[
      {id:'ins-m1',name:'Term protection',type:'Term insurance',status:'excluded',value:null,cover:5000000,version:3,fields:{'Recorded cover':'₹50,00,000','Cash value':'Not applicable','Premium cadence':'Yearly'}},
      {id:'ins-m2',name:'Savings policy',type:'Endowment / ULIP',status:'unvalued',value:null,version:2,fields:{'Recorded fund value':'Not provided','Premium cadence':'Monthly','Policy status':'Recorded'}}]
  },unclassified:[{id:'unc-m1',name:'Imported record',status:'unclassified'}],income:600000,outflows:90000,emergencyMonths:null,healthCover:null,taxUsed:64000},
  Kabir:{freshness:'No financial records requested',families:{Investments:[],Loans:[],Insurance:[]},unclassified:[],income:null,outflows:null,emergencyMonths:null,healthCover:null,taxUsed:null},
  Meera:{freshness:'Updated 29 Aug, 9:18 AM',families:{Investments:[{id:'inv-e1',name:'Starter deposit',type:'FD / RD',status:'valued',value:46850,version:1,fields:{'Recorded principal':'₹46,850','Cadence':'Monthly','Category':'FD / RD'}}],Loans:[],Insurance:[]},unclassified:[],income:null,outflows:null,emergencyMonths:null,healthCover:false,taxUsed:null}
};

const state={scenario:'complete',account:'Aarav',screen:'overview',family:null,holdingId:null,expandedHealth:null,loading:false,failedBlock:null,stale:false,offline:false,hasCache:true,permission:true,pendingSwitch:false,healthSaveFails:false,reminderFailed:false,teachingFundMode:'many',history:[]};
const $=id=>document.getElementById(id);
const clone=value=>JSON.parse(JSON.stringify(value));
let data=clone(fixtures);
let dialogReturnFocus=null;

function account(){return data[state.account]}
function allHoldings(a=account()){return Object.values(a.families).flat()}
function money(value){return value===0?'₹0':value==null?'Unknown':`₹${Math.round(value).toLocaleString('en-IN')}`}
function announce(message,urgent=false){const node=$(urgent?'urgent-announcement':'polite-announcement');node.textContent='';requestAnimationFrame(()=>{node.textContent=message})}
function log(message,urgent=false){$('route-log').textContent=message;announce(message,urgent)}
function setBanner(html='',kind='notice'){const node=$('banner');node.hidden=!html;node.className=`banner${kind==='error'?' error':''}`;node.innerHTML=html}
function routeStub(title,body='This controlled destination confirms the route. No production navigation or data changes occur.'){openDialog('Controlled destination',title,`<p>${body}</p>`,[{label:'Done',action:'close',className:'primary'}])}
function pushScreen(screen,family=null,holdingId=null){state.history.push({screen:state.screen,family:state.family,holdingId:state.holdingId});state.screen=screen;state.family=family;state.holdingId=holdingId;render();focusMain()}
function goBack(){const prior=state.history.pop()||{screen:'overview',family:null,holdingId:null};Object.assign(state,prior);render();focusMain()}
function focusMain(){requestAnimationFrame(()=>{$('app-content').focus()})}
function sourceDisclosure(label,unit,source,included,excluded){return `<details><summary>How this is formed</summary><dl class="health-detail"><dt>Label and unit</dt><dd>${label}, ${unit}</dd><dt>Source</dt><dd>${source}</dd><dt>Included</dt><dd>${included}</dd><dt>Not represented</dt><dd>${excluded}</dd></dl></details>`}
function statusText(record){return {valued:'Recorded value available',unvalued:'Recorded, value not provided',invalid:'Recorded value is invalid',excluded:'Recorded but excluded from this total'}[record.status]||'Needs classification'}
function familyTotal(name){const records=account().families[name];const valued=records.filter(r=>r.status==='valued'&&Number.isFinite(r.value));const sum=valued.reduce((n,r)=>n+r.value,0);const limited=records.filter(r=>r.status!=='valued').length;return {sum,valued:valued.length,limited,count:records.length}}
function overallStatus(){const records=allHoldings();return {count:records.length,limited:records.filter(r=>r.status!=='valued').length,unclassified:account().unclassified.length}}

function render(){
  $('account-label').textContent=`${state.account}'s hypothetical account`;
  $('back').hidden=state.screen==='overview'||!state.permission;
  setBanner();
  if(!state.permission){setBanner('Your session no longer has access. Financial information and drafts were cleared. <button data-route="Sign in again" class="primary">Sign in again</button>','error');$('app-content').innerHTML=`<section class="empty-state"><h1>Sign in to continue</h1><p>Previous-account financial information was removed immediately. No cached values remain on this screen.</p><button class="primary" data-route="Sign in again">Sign in again</button></section>`;bind();return}
  if(state.pendingSwitch){$('app-content').innerHTML=`<section aria-busy="true"><h1>Loading ${state.account}'s Portfolio</h1><p class="freshness">The prior account was cleared before this request started.</p>${'<div class="skeleton"></div>'.repeat(4)}</section>`;bind();return}
  if(state.loading){$('app-content').innerHTML=renderLoading();bind();return}
  if(state.offline&&!state.hasCache){setBanner('You are offline. No account-scoped saved view is available.');$('app-content').innerHTML=`<section class="empty-state"><h1>Portfolio is unavailable offline</h1><p>This is not an empty Portfolio and no amount is being treated as zero. Static teaching remains available.</p><div class="actions"><button data-route="Portfolio teaching">Read how Portfolio works</button><button data-action="restore">Connection restored</button></div></section>`;bind();return}
  if(state.offline)setBanner('You are offline. Showing last-known account-scoped information. Mutations are unavailable. <button data-action="restore">Connection restored</button>');
  else if(state.stale)setBanner('Showing last-known information from 10:42 AM. <button data-action="retry">Refresh now</button>');
  const renderers={overview:renderOverview,family:renderFamily,holding:renderHolding,health:renderHealth,concentration:renderConcentration,trend:renderTrend};
  $('app-content').innerHTML=renderers[state.screen]();
  bind();
}

function renderOverview(){
  if(state.failedBlock==='overview')return `<section><h1>Portfolio</h1><div class="error-card" role="alert"><h3>Recorded structure is unavailable</h3><p>This is a read failure, not an empty Portfolio. Portfolio Health and teaching routes remain available.</p><div class="actions"><button data-action="retry" class="primary">Try structure again</button><button data-screen="health">Open Portfolio Health</button></div></div></section>`;
  const a=account(),summary=overallStatus(),families=['Investments','Loans','Insurance'];
  const familyCards=families.map(name=>{const t=familyTotal(name);const value=name==='Insurance'?'Recorded fund value':name==='Loans'?'Recorded outstanding':'Recorded value';return `<button class="family-card" data-family="${name}"><span class="family-top"><strong>${name}</strong><span class="value">${t.count} ${t.count===1?'record':'records'}</span></span><span class="meta">${t.count?`${value}: ${t.valued?money(t.sum):'Unavailable'}${t.limited?`. ${t.limited} limited record${t.limited===1?'':'s'}.`:'.'}`:'Nothing recorded here. This does not prove real-world absence.'}</span></button>`}).join('');
  const allocation=families.map(name=>`<div class="allocation-item"><strong>${a.families[name].length}</strong><span>${name}</span></div>`).join('');
  return `<section><h1>Portfolio</h1><p class="freshness">${state.stale?'Last-known: ':''}${a.freshness}</p><p class="lede">A map of what is recorded, what is limited, and how each figure was formed.</p></section>
    <section class="section"><h2 class="section-heading">Recorded structure</h2><div class="structure"><div class="panel structure-summary"><span class="status">Classified records</span><div class="big-number">${summary.count}</div><span class="meta">Across three persistent families. No net-worth subtraction is calculated.</span></div><div class="panel"><span class="status">Needs review</span><div class="big-number">${summary.limited+summary.unclassified}</div><span class="meta">Limited or unclassified records, never counted as zero.</span></div></div>${sourceDisclosure('Recorded structure','records','Owned holding records','Each classified record once','Rupee allocation, performance, quality or net worth')}</section>
    ${summary.unclassified?`<section class="section"><button class="error-card" data-route="Review unclassified record"><strong>${summary.unclassified} record needs classification</strong><span class="meta">It is outside all three family totals until you review it.</span></button></section>`:''}
    <section class="section"><h2 class="section-heading">Families</h2><div class="family-list">${familyCards}</div></section>
    <section class="section"><h2 class="section-heading">Allocation by record count</h2><div class="panel">${summary.count?`<div class="allocation" aria-label="Allocation by record count: ${families.map(n=>`${n} ${a.families[n].length}`).join(', ')}">${allocation}</div>`:'<p>There are no classified records to count.</p>'}<p class="limits">This counts records, not rupees. It cannot show asset weighting, risk, quality or net worth.</p>${sourceDisclosure('Portfolio allocation','records','Owned classified holdings','Each classified record once','Rupee weight, asset mix, risk or performance')}</div></section>
    <section class="section"><h2 class="section-heading">Portfolio Health</h2><button class="panel" data-screen="health"><strong>${healthAvailability()}</strong><span class="meta">Separate factual mechanisms. No composite score or grade.</span></button></section>
    <section class="section"><h2 class="section-heading">Explore structure</h2><div class="link-list"><button data-screen="concentration">Category concentration</button><button data-screen="trend">Why no trend appears</button></div></section>
    <section class="section"><h2 class="section-heading">Data controls</h2><div class="link-list"><button data-route="Export Portfolio data">Export my data</button><button class="danger" data-route="Delete account preview">Delete account</button></div></section>`;
}

function renderLoading(){
  if(state.screen==='health')return `<section aria-busy="true" role="status"><h1>Loading Portfolio Health</h1><p class="freshness">Checking four independent mechanism groups</p><div class="health-list">${'<div class="skeleton"></div>'.repeat(4)}</div></section>`;
  if(state.screen==='family')return `<section aria-busy="true" role="status"><h1>${state.family}</h1><p class="freshness">Checking this family without showing an empty state</p>${'<div class="skeleton"></div>'.repeat(3)}</section>`;
  return `<section aria-busy="true" role="status"><h1>Loading Portfolio</h1><p class="freshness">Checking ${state.account}'s current records</p>${'<div class="skeleton"></div>'.repeat(4)}</section>`;
}

function renderFamily(){
  const name=state.family,records=account().families[name],t=familyTotal(name);
  if(state.failedBlock==='family')return `<section><h1>${name}</h1><div class="error-card" role="alert"><h3>${name} could not load</h3><p>Other Portfolio sections remain available. This is not an empty-family result.</p><div class="actions"><button class="primary" data-action="retry">Try ${name} again</button><button data-action="back">Back to Portfolio</button></div></div></section>`;
  if(!records.length)return `<section><h1>${name}</h1><p class="freshness">No records returned for this family</p><div class="empty-state"><h3>Nothing recorded here</h3><p>${emptyTeaching(name)}</p><p>This does not mean you need one, and it does not prove that none exists outside FinTutor.</p><div class="actions vertical"><button data-action="walkthrough">Understand ${name.toLowerCase()}</button><button data-route="Ask Arya about ${name}">Ask Arya</button><button data-action="capture">I think I have one</button><button class="text-action" data-action="manual-add">Add manually instead</button></div></div></section>`;
  const rows=records.map(r=>`<button class="holding-card" data-holding="${r.id}"><span class="holding-top"><strong>${r.name}</strong><span class="status ${r.status}">${statusText(r)}</span></span><span class="meta">${r.type}${r.status==='valued'?` | ${money(r.value)}`:''}</span></button>`).join('');
  return `<section><h1>${name}</h1><p class="freshness">${account().freshness}</p><div class="panel"><div class="family-top"><strong>${t.count} ${t.count===1?'record':'records'}</strong><span class="value">${t.valued?money(t.sum):'Value unavailable'}</span></div><span class="meta">${t.valued} valued. ${t.limited} limited. The known amount is not called a complete total.</span>${sourceDisclosure(`${name} family total`,name==='Loans'?'rupees outstanding':'recorded rupees','Owned holding records','Recognized finite valuation fields','Unvalued, invalid, excluded and unclassified records')}</div></section><section class="section"><h2 class="section-heading">Every recorded item</h2><div class="family-list">${rows}</div><div class="actions"><button data-action="walkthrough">Understand this family</button><button class="text-action" data-action="manual-add">Add manually</button></div></section>`;
}

function renderHolding(){
  const r=allHoldings().find(x=>x.id===state.holdingId);if(!r)return `<section><h1>Record unavailable</h1><p>This record is no longer in the authoritative fixture.</p></section>`;
  const disabled=state.offline?'disabled aria-disabled="true"':'';
  return `<section><h1>${r.name}</h1><p class="freshness">${r.type} | saved version ${r.version}</p><p class="lede">Recorded fields are shown separately from values calculated elsewhere.</p><div class="field-grid">${Object.entries(r.fields).map(([k,v])=>`<div class="field"><span>${k}</span><strong>${v||'Unknown'}</strong></div>`).join('')}</div><p class="limits">Internal record identifiers and aliases are not shown as primary content. Arya receives a server-resolved alias, never this display name.</p><div class="actions vertical"><button data-action="ask-holding">Ask Arya about the mechanism</button><button data-action="edit" ${disabled}>Edit saved fields</button><button data-action="recategorize" ${disabled}>Change category</button><button data-action="conflict" ${disabled}>Test stale edit conflict</button><button data-action="lost-response" ${disabled}>Test lost save response</button><button class="danger" data-action="delete" ${disabled}>Delete record</button></div></section>`;
}

function healthAvailability(){const a=account();const groups=[a.income!=null&&a.outflows!=null,(a.healthCover!=null||a.families.Insurance.some(r=>r.type==='Term insurance')),a.emergencyMonths!=null,a.taxUsed!=null];return `${groups.filter(Boolean).length} of 4 mechanism groups available`}
function healthRows(){
  const a=account(),term=a.families.Insurance.find(r=>r.type==='Term insurance'),investment=a.income!=null&&a.outflows!=null?Math.min(100,(a.outflows/a.income)*1000):null,ratio=term&&a.income?term.cover/a.income:null;
  return [
    {id:'investment',name:'Investment rate',value:investment==null?'Unknown':`${investment.toFixed(1)} points`,unit:'points from a percentage mechanism',mechanism:'Recorded annual investing outflow divided by accepted annual income. A 10% rate maps to 100 points.',sources:'Accepted annual income and included recurring investment outflows.',missing:investment==null?'Income or investing outflow is not available.':'None for this fixture.'},
    {id:'insurance',name:'Insurance records',value:(a.healthCover!=null||term)?'Components available':'Unknown',unit:'factual states and a descriptive ratio',mechanism:`Health cover: ${a.healthCover==null?'not provided':a.healthCover?'confirmed yes':'confirmed no'}. Term cover: ${term?'recorded':'none recorded'}. Cover-to-income ratio: ${ratio?ratio.toFixed(2)+'×':'unknown'}.`,sources:'Optional account-owned health context, owned term record and accepted annual income.',missing:!ratio?'Cover amount or income is unavailable. No adequacy threshold is applied.':'No combined score or adequacy threshold is applied.'},
    {id:'emergency',name:'Emergency buffer',value:a.emergencyMonths==null?'Unknown':`${a.emergencyMonths} months`,unit:'user-confirmed months',mechanism:'The user-confirmed months value is displayed on a 12-month teaching scale.',sources:'Optional account-owned financial context.',missing:a.emergencyMonths==null?'Not provided. It is not inferred from balances.':'None for this fixture.'},
    {id:'tax',name:'Tax utilisation',value:a.taxUsed==null?'Unknown':`${money(a.taxUsed)} recorded`,unit:'rupees against the ₹1,50,000 teaching denominator',mechanism:'Included recorded tax-advantaged contributions divided by ₹1,50,000.',sources:'Included owned holding contribution fields and approved cadences.',missing:a.taxUsed==null?'No included contribution source is available.':'This does not claim tax savings or recommend a contribution.'}
  ];
}
function renderHealth(){
  if(state.failedBlock==='health')return `<section><h1>Portfolio Health</h1><div class="error-card" role="alert"><h3>One Health source is unavailable</h3><p>Other mechanisms remain inspectable and the failed source is not treated as zero.</p><button class="primary" data-action="retry">Try Health source again</button></div>${renderHealthList(true)}</section>`;
  const disabled=state.offline?'disabled aria-disabled="true"':'';
  return `<section><h1>Portfolio Health</h1><p class="freshness">${healthAvailability()}</p><p class="lede">Four transparent mechanism groups. They are not averaged, graded or ranked.</p></section>${renderHealthList(false)}<section class="section"><div class="panel context-box"><h2>Optional context</h2><p class="meta">Emergency months and health-cover presence are optional, account-owned, changeable, clearable, exportable and deleted with the account. They are never inferred or required.</p><div class="actions"><button data-action="edit-context" ${disabled}>View or change context</button><button class="text-action" data-action="clear-context" ${disabled}>Clear optional context</button></div></div></section>`;
}
function renderHealthList(failed){return `<section class="section"><h2 class="section-heading">Individual mechanisms</h2><div class="health-list">${healthRows().map((r,i)=>{const unavailable=failed&&i===1;const expanded=state.expandedHealth===r.id;return `<button class="health-row" data-health="${r.id}" aria-expanded="${expanded}" aria-controls="health-${r.id}"><span class="health-top"><strong>${r.name}</strong><span class="value">${unavailable?'Unavailable':r.value}</span></span><span class="meta">${r.unit}</span>${expanded?`<div class="health-detail" id="health-${r.id}"><dl><dt>Mechanism</dt><dd>${unavailable?'This source failed locally. Retry does not reload other mechanisms.':r.mechanism}</dd><dt>Sources</dt><dd>${r.sources}</dd><dt>Boundary or missing input</dt><dd>${r.missing}</dd></dl></div>`:''}</button>`}).join('')}</div></section>`}

function renderConcentration(){
  const supported=state.teachingFundMode==='zero'?[]:state.teachingFundMode==='one'?[{type:'Equity mutual fund'}]:account().families.Investments.filter(r=>['Equity mutual fund','Debt mutual fund'].includes(r.type));const equity=supported.filter(r=>r.type==='Equity mutual fund').length,debt=supported.filter(r=>r.type==='Debt mutual fund').length;
  return `<section><h1>Category concentration</h1><p class="lede">A count of supported broad mutual-fund categories, not a verdict.</p>${supported.length?`<div class="panel"><div class="big-number">${supported.length} ${supported.length===1?'fund':'funds'}</div><div class="allocation"><div class="allocation-item"><strong>${equity}</strong><span>Equity category</span></div><div class="allocation-item"><strong>${debt}</strong><span>Debt category</span></div></div></div>`:`<div class="empty-state"><h3>No supported fund records to count</h3><p>This is not 0% diversified and does not imply a missing investment.</p></div>`}<div class="teaching-card section"><h2>What this shows</h2><p>How many owned equity and debt mutual-fund records appear in each supported broad category.</p><h2>What this cannot tell</h2><p>Scheme or stock overlap, rupee weighting, risk, adequacy, performance, diversification quality or an action to take.</p></div><div class="actions"><button data-funds="zero">Test zero</button><button data-funds="one">Test one</button><button data-funds="many">Test many</button><button data-route="Inspect contributing investments">Inspect records</button></div></section>`;
}
function renderTrend(){return `<section><h1>Why no trend appears</h1><div class="teaching-card"><h2>One balance is not a trend</h2><p>A trend needs comparable snapshots taken at different times using the same definition. FinTutor has not stored that history in this fixture.</p><p class="limits">No line chart, return, benchmark, performance claim or past value is invented.</p><div class="actions"><button data-route="Ask Arya about comparable snapshots">Ask Arya</button><button data-action="back">Back to Portfolio</button></div></div></section>`}

function emptyTeaching(name){return {Investments:'Learn how ownership, liquidity, return and risk differ across broad investment mechanisms.',Loans:'Learn how principal, interest, term and repayment cadence shape a borrowing record.',Insurance:'Learn how risk transfer, premium, benefit and cash value are different concepts.'}[name]}

function openDialog(label,title,body,actions){dialogReturnFocus=document.activeElement;$('dialog-label').textContent=label;$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog-actions').innerHTML=actions.map(a=>`<button value="${a.action}" data-dialog-action="${a.action}" class="${a.className||''}">${a.label}</button>`).join('');$('action-dialog').showModal()}
function closeDialog(){if($('action-dialog').open)$('action-dialog').close();requestAnimationFrame(()=>dialogReturnFocus?.focus())}
function currentHolding(){return allHoldings().find(r=>r.id===state.holdingId)}
function holdingLocation(id){for(const [family,records] of Object.entries(account().families)){const index=records.findIndex(r=>r.id===id);if(index>=0)return {family,index,record:records[index]}}return null}

function walkthrough(){openDialog('Optional teaching',`Understand ${state.family}`,`<p>${emptyTeaching(state.family)}</p><p>No personal numbers are used. You can close at any time, ask Arya, or start capture only if you choose.</p>`,[{label:'Close',action:'close'},{label:'Ask Arya',action:'arya'},{label:'I think I have one',action:'capture',className:'primary'}])}
function manualAdd(){openDialog('Secondary manual path',`Add to ${state.family}`,`<div class="form-field"><label for="new-name">Your label</label><input id="new-name" value="New hypothetical record"><span class="helper">A display label stays in the authenticated interface.</span></div><div class="form-field"><label for="new-type">Record type</label><select id="new-type"><option>Equity mutual fund</option><option>Debt mutual fund</option><option>FD / RD</option></select></div><p>Controlled preview only. Saving adds one in-memory record with a generated internal alias.</p>`,[{label:'Cancel',action:'close'},{label:'Add record',action:'create',className:'primary'}])}
function editHolding(){const r=currentHolding();openDialog('Edit draft',`Edit ${r.name}`,`<p class="helper">Saved version ${r.version} remains authoritative until confirmation.</p><div class="form-field"><label for="edit-name">Display label</label><input id="edit-name" value="${r.name}"><span class="helper">Draft, not saved.</span><span class="field-error" id="edit-error"></span></div>`,[{label:'Cancel',action:'close'},{label:'Test invalid',action:'invalid'},{label:'Save',action:'save-edit',className:'primary'}])}
function recategorize(){const r=currentHolding();openDialog('Field-loss review','Change category',`<p>Changing <strong>${r.name}</strong> from ${r.type} to Debt mutual fund will remove fields that do not apply:</p><ul><li>Equity category</li><li>Existing valuation provenance</li></ul><p>The record stays unchanged until you confirm.</p>`,[{label:'Cancel',action:'close'},{label:'Confirm change',action:'confirm-category',className:'primary'}])}
function conflictDialog(kind='edit'){const r=currentHolding();openDialog('Fresh comparison','This record changed elsewhere',`<div class="comparison"><div><strong>Current version ${r.version+1}</strong><p>${r.name}, ₹2,91,640</p></div><div><strong>Your proposal</strong><p>${r.name} updated, ₹2,83,750</p></div></div><p>Review the current record before choosing again. Nothing was overwritten.</p>`,[{label:'Cancel',action:'close'},{label:'Revise',action:kind==='delete'?'close':'edit'},{label:'Reconfirm',action:kind==='delete'?'delete-success':'save-edit',className:'primary'}])}
function deleteDialog(){const r=currentHolding();openDialog('Deletion impact',`Delete ${r.name}?`,`<p>This removes exactly this FinTutor record and its declared links. It does not claim that a real-world account or obligation changed.</p><ul>${(r.links||['No linked goals or reminders']).map(x=>`<li>${x}</li>`).join('')}<li>Affected family totals and record counts recalculate</li></ul>`,[{label:'Cancel',action:'close'},{label:'Test stale review',action:'delete-conflict'},{label:'Delete record',action:'delete-success',className:'danger'}])}
function contextDialog(){const a=account();openDialog('Optional account-owned context','View or change context',`<p>Optional. Used only in Portfolio Health, available across your signed-in devices, included in export, and deleted with the account.</p><div class="form-field"><label for="emergency-months">Emergency buffer in months</label><input id="emergency-months" inputmode="decimal" value="${a.emergencyMonths??''}"><span class="helper">Leave blank for not provided. Never inferred from balances.</span></div><div class="form-field"><label for="health-cover">Health insurance presence</label><select id="health-cover"><option value="unknown" ${a.healthCover==null?'selected':''}>Prefer not to answer</option><option value="yes" ${a.healthCover===true?'selected':''}>Yes, confirmed</option><option value="no" ${a.healthCover===false?'selected':''}>No, confirmed</option></select><span class="helper">This does not affect access or rewards.</span></div><div id="context-error" class="field-error" role="alert"></div>`,[{label:'Cancel',action:'close'},{label:'Test save failure',action:'fail-context'},{label:'Save context',action:'save-context',className:'primary'}])}

function dialogAction(action){
  const r=currentHolding();
  if(action==='close'){closeDialog();return}
  if(action==='arya'){closeDialog();routeStub('Arya','No personal number is sent until the user explicitly chooses a teaching handoff.');return}
  if(action==='capture'){closeDialog();routeStub('AI-assisted capture','Structured capture asks for explicit confirmation before creating a record.');return}
  if(action==='create'){const name=$('new-name').value.trim()||'Hypothetical record';account().families[state.family].push({id:`new-${Date.now()}`,name,type:$('new-type').value,status:'unvalued',value:null,version:1,fields:{'Recorded value':'Not provided','Category':$('new-type').value}});closeDialog();render();log(`${name} added once in fixture memory with authoritative version 1.`);return}
  if(action==='invalid'){$('edit-name').value='';$('edit-error').textContent='Display label cannot be empty. Saved record is unchanged.';$('edit-name').focus();log('Draft validation failed. Authoritative record unchanged.',true);return}
  if(action==='edit'){closeDialog();editHolding();return}
  if(action==='save-edit'){const input=$('edit-name');if(input&&!input.value.trim()){$('edit-error').textContent='Display label cannot be empty. Saved record is unchanged.';input.focus();return}if(r){r.name=input?.value.trim()||r.name;r.version+=1;r.fields['Last fixture update']='Recalculated from saved inputs'}closeDialog();render();log('Record saved once. Affected views recalculated without reward or judgment.');return}
  if(action==='confirm-category'){const loc=holdingLocation(r.id);loc.record.type='Debt mutual fund';loc.record.status='unvalued';loc.record.value=null;loc.record.version+=1;loc.record.fields={'Recorded value':'Not provided','Category':'Debt mutual fund'};closeDialog();render();log('Category changed after field-loss confirmation.');return}
  if(action==='delete-conflict'){closeDialog();conflictDialog('delete');return}
  if(action==='delete-success'){const loc=holdingLocation(r.id);loc.record.version+=1;loc.record._deleteCommitted=true;account().families[loc.family].splice(loc.index,1);closeDialog();state.screen='family';state.family=loc.family;state.holdingId=null;state.reminderFailed=true;render();setBanner('Record deletion committed. Reminder cleanup failed separately. <button data-action="retry-reminder">Retry reminder</button>','error');log('Record removed once. Reminder failure did not roll back the committed deletion.',true);return}
  if(action==='fail-context'){state.healthSaveFails=true;$('context-error').textContent='Could not save. Prior authoritative context remains current.';log('Context save failed. Prior value preserved.',true);return}
  if(action==='save-context'){if(state.healthSaveFails){$('context-error').textContent='Retry available. Prior authoritative context remains current.';state.healthSaveFails=false;return}const months=$('emergency-months').value.trim(),health=$('health-cover').value;account().emergencyMonths=months===''?null:Number(months);account().healthCover=health==='unknown'?null:health==='yes';closeDialog();render();log('Optional account-owned context saved. Dependent measures recalculated; no reward emitted.');return}
}

function handleAction(action){
  if(action==='back'){goBack();return}if(action==='retry'){state.failedBlock=null;state.stale=false;state.offline=false;render();focusMain();log('Only the affected source refreshed successfully.');return}if(action==='restore'){state.offline=false;state.stale=true;state.hasCache=true;render();log('Connection restored. Financial content remains stale until explicit refresh.');return}if(action==='walkthrough'){walkthrough();return}if(action==='capture'){routeStub('AI-assisted capture','Nothing is written until the user reviews and confirms structured fields.');return}if(action==='manual-add'){manualAdd();return}if(action==='ask-holding'){routeStub('Arya mechanism handoff','Model boundary receives Alias-01 and approved characteristics. It does not receive the visible display name or raw record identifier.');return}if(action==='edit'){editHolding();return}if(action==='recategorize'){recategorize();return}if(action==='conflict'){conflictDialog();return}if(action==='lost-response'){const r=currentHolding();r.version+=1;render();log('Save response was lost. Authoritative read found the new version, so no duplicate write was sent.');return}if(action==='delete'){deleteDialog();return}if(action==='edit-context'){contextDialog();return}if(action==='clear-context'){account().emergencyMonths=null;account().healthCover=null;render();log('Optional context cleared across the account fixture. Dependent measures are now unknown; no reward emitted.');return}if(action==='retry-reminder'){state.reminderFailed=false;render();log('Reminder cleanup retried idempotently. The record deletion was not repeated.');return}
}

function bind(){
  document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>pushScreen('family',b.dataset.family));
  document.querySelectorAll('[data-holding]').forEach(b=>b.onclick=()=>pushScreen('holding',state.family,b.dataset.holding));
  document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>pushScreen(b.dataset.screen));
  document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>routeStub(b.dataset.route));
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));
  document.querySelectorAll('[data-health]').forEach(b=>b.onclick=()=>{state.expandedHealth=state.expandedHealth===b.dataset.health?null:b.dataset.health;render();requestAnimationFrame(()=>document.querySelector(`[data-health="${b.dataset.health}"]`)?.focus())});
  document.querySelectorAll('[data-funds]').forEach(b=>b.onclick=()=>{state.teachingFundMode=b.dataset.funds;render();log(`Concentration fixture now has ${b.dataset.funds} supported fund records.`)});
}

function applyScenario(name){
  data=clone(fixtures);Object.assign(state,{scenario:name,account:name==='empty'?'Kabir':name==='complete'||name==='isolation'?'Aarav':'Mira',screen:name==='health'?'health':name==='teaching'?'concentration':'overview',family:null,holdingId:null,expandedHealth:null,loading:false,failedBlock:null,stale:false,offline:false,hasCache:true,permission:true,pendingSwitch:false,healthSaveFails:false,reminderFailed:false,teachingFundMode:'many',history:[]});
  const s=scenarios[name];$('scenario-title').textContent=s.title;$('scenario-prompt').textContent=s.prompt;$('scenario-fixture').textContent=`Fixture: ${s.fixture}`;render();log(`Loaded task: ${s.title}.`)
}

$('scenario').addEventListener('change',e=>applyScenario(e.target.value));
$('back').addEventListener('click',goBack);
$('refresh').addEventListener('click',()=>{if(state.offline){log('Refresh was not sent while offline. Restore the connection first.');return}state.stale=false;state.failedBlock=null;render();log('Portfolio refreshed explicitly.')});
$('action-dialog').addEventListener('close',()=>requestAnimationFrame(()=>dialogReturnFocus?.focus()));
$('action-dialog').addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();closeDialog()}});
$('dialog-actions').addEventListener('click',e=>{const button=e.target.closest('[data-dialog-action]');if(button){e.preventDefault();dialogAction(button.dataset.dialogAction)}});
document.querySelectorAll('[data-fixture]').forEach(button=>button.addEventListener('click',()=>{
  const action=button.dataset.fixture;
  if(action==='reset'){applyScenario(state.scenario);return}
  if(action==='loading'){state.loading=true;render();log('Neutral account-scoped loading shell displayed.');setTimeout(()=>{state.loading=false;render();log('Current account loaded without an empty-state flash.')},450);return}
  if(action==='fail-block'){state.failedBlock=state.screen==='family'?'family':state.screen==='health'?'health':'overview';render();log('Current source failed locally. Other independent content remains available.',true);return}
  if(action==='stale'){state.stale=true;render();log('Current values marked last-known with a timestamp.');return}
  if(action==='offline-cache'){state.offline=true;state.stale=true;state.hasCache=true;render();log('Offline with scoped cache. Mutations unavailable; no silent retry.');return}
  if(action==='offline-empty'){state.offline=true;state.hasCache=false;render();log('Offline without cache. No empty or zero financial claim appears.');return}
  if(action==='unowned'){routeStub('Record unavailable','The same neutral not-found result appears whether the record does not exist or belongs to another subject. No record detail is disclosed.');log('Unowned record request returned neutral not-found with no existence leak.');return}
  if(action==='permission'){state.permission=false;state.history=[];closeDialog();render();focusMain();log('Permission lost. Financial content and drafts cleared immediately.',true);return}
  if(action==='switch'){const prior=state.account;state.account=prior==='Meera'?'Aarav':'Meera';state.pendingSwitch=true;state.history=[];state.family=null;state.holdingId=null;closeDialog();render();log(`Cleared ${prior}'s content before loading ${state.account}.`);setTimeout(()=>{state.pendingSwitch=false;state.screen='overview';render();focusMain();log(`Loaded ${state.account}. Discarded a late ${prior} response.`)},500);return}
  if(action==='signout'){state.permission=false;state.history=[];closeDialog();render();focusMain();log('Signed out. All subject-scoped Portfolio state was actively cleared.',true)}
}));

window.PortfolioPrototype={state,fixtures:clone(fixtures),scenarios:Object.keys(scenarios),getSnapshot:()=>clone({state,data})};
applyScenario('complete');
